@push('scripts')
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script>
<script>
function printQr(name,code,token){const holder=document.createElement('div');new QRCode(holder,{text:token,width:240,height:240});setTimeout(()=>{const image=holder.querySelector('img')?.src||holder.querySelector('canvas')?.toDataURL();const win=window.open('','_blank','width=420,height=520');win.document.write(`<html><head><title>QR ${code}</title><style>body{font:14px sans-serif;text-align:center;padding:35px;color:#102334}img{width:240px;height:240px}small{color:#687987}</style></head><body><h2>${name}</h2><p>${code}</p><img src="${image}"><p><small>${token}</small></p><script>window.onload=()=>{window.print()}<\/script></body></html>`);win.document.close()},300)}
</script>
@endpush
